  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.notifications.ReservationNotificationListener;
  6	import hotel.rooms.Room;
  7	import hotel.rooms.Rooms;
  8	import java.math.BigDecimal;
  9	import java.util.ArrayList;
 10	import java.util.List;
 11	
 12	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 13	public final class ReservationService {
 14	
 15	    static final String HOTEL_NAME = "Pousada Maré Alta";
 16	
 17	    private final Rooms rooms;
 18	    private final ReservationStore store;
 19	    private final PriceCalculator priceCalculator;
 20	    private final EmailSender emailSender;
 21	    private final List<ReservationNotificationListener> notificationListeners;
 22	
 23	    public ReservationService(
 24	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 25	        this(rooms, store, priceCalculator, emailSender, new ArrayList<>());
 26	    }
 27	
 28	    public ReservationService(
 29	            Rooms rooms,
 30	            ReservationStore store,
 31	            PriceCalculator priceCalculator,
 32	            EmailSender emailSender,
 33	            List<ReservationNotificationListener> notificationListeners) {
 34	        this.rooms = rooms;
 35	        this.store = store;
 36	        this.priceCalculator = priceCalculator;
 37	        this.emailSender = emailSender;
 38	        this.notificationListeners = notificationListeners;
 39	    }
 40	
 41	    public synchronized Reservation create(NewReservation request) {
 42	        if (!request.checkOut().isAfter(request.checkIn())) {
 43	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 44	        }
 45	        if (request.guests() < 1) {
 46	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 47	        }
 48	        Room room = rooms.find(request.roomNumber())
 49	                .orElseThrow(() -> new HotelException(
 50	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 51	        if (request.guests() > room.capacity()) {
 52	            throw new HotelException(
 53	                    ErrorCode.CAPACITY_EXCEEDED,
 54	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 55	        }
 56	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 57	            throw new HotelException(
 58	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 59	        }
 60	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 61	        return store.add(request, price);
 62	    }
 63	
 64	    public Reservation find(long reservationId) {
 65	        return store.find(reservationId)
 66	                .orElseThrow(() -> new HotelException(
 67	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 68	    }
 69	
 70	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 71	    public synchronized Reservation confirm(long reservationId) {
 72	        Reservation reservation = find(reservationId);
 73	        if (reservation.status() != ReservationStatus.PENDING) {
 74	            throw notAllowed(reservation, "confirm");
 75	        }
 76	        reservation.confirmPayment();
 77	        store.update(reservation);
 78	        Room room = roomOf(reservation);
 79	        ReservationReceipt receipt = new ReservationReceipt(reservation, room);
 80	        emailSender.send(
 81	                reservation.guest().email(),
 82	                "Reserva confirmada - " + HOTEL_NAME,
 83	                confirmationEmailBody(reservation, receipt));
 84	        for (ReservationNotificationListener listener : notificationListeners) {
 85	            listener.onReservationConfirmed(reservation, room);
 86	        }
 87	        return reservation;
 88	    }
 89	
 90	    /**
 91	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 92	     * reservation was never paid, so nothing comes back).
 93	     */
 94	    public synchronized Reservation cancel(long reservationId) {
 95	        Reservation reservation = find(reservationId);
 96	        if (reservation.status() != ReservationStatus.PENDING
 97	                && reservation.status() != ReservationStatus.CONFIRMED) {
 98	            throw notAllowed(reservation, "cancel");
 99	        }
100	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
101	        BigDecimal refund = switch (reservation.ratePlan()) {
102	            case STANDARD -> reservation.amountPaid();
103	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
104	        };
105	        reservation.cancel(refund);
106	        store.update(reservation);
107	        if (wasConfirmed) {
108	            Room room = roomOf(reservation);
109	            for (ReservationNotificationListener listener : notificationListeners) {
110	                listener.onReservationCancelled(reservation, room);
111	            }
112	        }
113	        return reservation;
114	    }
115	
116	    public synchronized Reservation checkIn(long reservationId) {
117	        Reservation reservation = find(reservationId);
118	        if (reservation.status() != ReservationStatus.CONFIRMED) {
119	            throw notAllowed(reservation, "check in");
120	        }
121	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
122	        store.update(reservation);
123	        return reservation;
124	    }
125	
126	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
127	    public synchronized ReservationReceipt checkOut(long reservationId) {
128	        Reservation reservation = find(reservationId);
129	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
130	            throw notAllowed(reservation, "check out");
131	        }
132	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
133	        store.update(reservation);
134	        return new ReservationReceipt(reservation, roomOf(reservation));
135	    }
136	
137	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
138	    public ReservationReceipt receiptCopy(long reservationId) {
139	        Reservation reservation = find(reservationId);
140	        if (!reservation.isPaid()) {
141	            throw notAllowed(reservation, "issue a receipt for");
142	        }
143	        return new ReservationReceipt(reservation, roomOf(reservation));
144	    }
145	
146	    private Room roomOf(Reservation reservation) {
147	        return rooms.find(reservation.roomNumber()).orElseThrow();
148	    }
149	
150	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
151	        return "Olá, " + reservation.guest().name() + "!\n\n"
152	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
153	                + receipt.text() + "\n"
154	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
155	                + "Até breve!\n";
156	    }
157	
158	    private static HotelException notAllowed(Reservation reservation, String operation) {
159	        return new HotelException(
160	                ErrorCode.OPERATION_NOT_ALLOWED,
161	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
162	    }
163	}
