  2	
  3	import hotel.messages.EmailSender;
  4	import hotel.messages.SentMessages;
  5	import hotel.notifications.FinanceNotificationListener;
  6	import hotel.notifications.GovernanceNotificationListener;
  7	import hotel.reports.OccupancyReport;
  8	import hotel.reports.RevenueReport;
  9	import hotel.reservations.PriceCalculator;
 10	import hotel.reservations.ReservationService;
 11	import hotel.reservations.ReservationStore;
 12	import hotel.rooms.Rooms;
 13	import hotel.web.HttpApi;
 14	import io.javalin.Javalin;
 15	import java.util.Arrays;
 16	import java.util.List;
 17	import javax.sql.DataSource;
 18	
 19	/** Puts the inn's pieces together and runs the HTTP server. */
 20	public final class Hotel {
 21	
 22	    private final Javalin server;
 23	
 24	    public Hotel(DataSource dataSource) {
 25	        Rooms rooms = new Rooms(dataSource);
 26	        ReservationStore store = new ReservationStore(dataSource);
 27	        SentMessages sentMessages = new SentMessages(dataSource);
 28	        EmailSender emailSender = new EmailSender(sentMessages);
 29	        List<hotel.notifications.ReservationNotificationListener> notificationListeners = Arrays.asList(
 30	                new GovernanceNotificationListener(emailSender),
 31	                new FinanceNotificationListener(emailSender)
 32	        );
 33	        ReservationService reservations =
 34	                new ReservationService(rooms, store, new PriceCalculator(), emailSender, notificationListeners);
 35	        HttpApi api = new HttpApi(
 36	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
 37	        this.server = api.server();
 38	    }
 39	
 40	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
 41	    public int start(int port) {
 42	        server.start(port);
 43	        return server.port();
 44	    }
 45	
 46	    public void stop() {
 47	        server.stop();
 48	    }
 49	
 50	    public static void main(String[] args) {
 51	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 52	        Database database = new Database(System.getenv());
 53	        new Hotel(database.dataSource()).start(port);
 54	    }
 55	}
  1	package hotel.messages;
  2	
  3	/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
  4	public final class EmailSender {
  5	
  6	    private final SentMessages sentMessages;
  7	
  8	    public EmailSender(SentMessages sentMessages) {
  9	        this.sentMessages = sentMessages;
 10	    }
 11	
 12	    public Message send(String to, String subject, String body) {
 13	        return sentMessages.add("EMAIL", to, subject, body);
 14	    }
 15	}

