 85	            listener.onReservationConfirmed(reservation, room);
 86	        }
 87	        return reservation;
 88	    }
 89	
 90	    /**
 91	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 92	     * reservation was never paid, so nothing comes back).
 93	     */
 94	    public synchronized Reservation cancel(long reservationId) {
 95	        Reservation reservation = find(reservationId);
 96	        if (reservation.status() != ReservationStatus.PENDING
 97	                && reservation.status() != ReservationStatus.CONFIRMED) {
 98	            throw notAllowed(reservation, "cancel");
 99	        }
100	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
101	        BigDecimal refund = switch (reservation.ratePlan()) {
102	            case STANDARD -> reservation.amountPaid();
103	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
104	        };
105	        reservation.cancel(refund);
106	        store.update(reservation);
107	        if (wasConfirmed) {
108	            Room room = roomOf(reservation);
109	            for (ReservationNotificationListener listener : notificationListeners) {
110	                listener.onReservationCancelled(reservation, room);
111	            }
112	        }
113	        return reservation;
114	    }
115	
116	    public synchronized Reservation checkIn(long reservationId) {
117	        Reservation reservation = find(reservationId);
118	        if (reservation.status() != ReservationStatus.CONFIRMED) {
119	            throw notAllowed(reservation, "check in");
120	        }
121	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
122	        store.update(reservation);
123	        return reservation;
124	    }
125	
126	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
127	    public synchronized ReservationReceipt checkOut(long reservationId) {
128	        Reservation reservation = find(reservationId);
129	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
130	            throw notAllowed(reservation, "check out");
131	        }
132	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
133	        store.update(reservation);
134	        return new ReservationReceipt(reservation, roomOf(reservation));
135	    }
136	
137	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
138	    public ReservationReceipt receiptCopy(long reservationId) {
139	        Reservation reservation = find(reservationId);
140	        if (!reservation.isPaid()) {
141	            throw notAllowed(reservation, "issue a receipt for");
142	        }
143	        return new ReservationReceipt(reservation, roomOf(reservation));
144	    }
145	
146	    private Room roomOf(Reservation reservation) {
147	        return rooms.find(reservation.roomNumber()).orElseThrow();
148	    }
149	
150	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
151	        return "Olá, " + reservation.guest().name() + "!\n\n"
152	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
153	                + receipt.text() + "\n"
154	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
155	                + "Até breve!\n";
156	    }
157	
158	    private static HotelException notAllowed(Reservation reservation, String operation) {
159	        return new HotelException(
160	                ErrorCode.OPERATION_NOT_ALLOWED,
161	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
162	    }
163	}
