140	package hotel.messages;
141	
142	import java.sql.Connection;
143	import java.sql.PreparedStatement;
144	import java.sql.ResultSet;
145	import java.sql.SQLException;
146	import java.util.ArrayList;
147	import java.util.List;
148	import javax.sql.DataSource;
149	
150	/** Every message the inn sent, so the front desk can check what each guest received. */
151	public final class SentMessages {
152	
153	    private final DataSource dataSource;
154	
155	    public SentMessages(DataSource dataSource) {
156	        this.dataSource = dataSource;
157	    }
158	
159	    Message add(String channel, String to, String subject, String body) {
160	        try (Connection connection = dataSource.getConnection();
161	                PreparedStatement insert = connection.prepareStatement(
162	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
163	            insert.setString(1, channel);
164	            insert.setString(2, to);
165	            insert.setString(3, subject);
166	            insert.setString(4, body);
167	            try (ResultSet generated = insert.executeQuery()) {
168	                generated.next();
169	                return new Message(generated.getLong("id"), channel, to, subject, body);
170	            }
171	        } catch (SQLException failure) {
172	            throw new IllegalStateException("could not keep the message to " + to, failure);
173	        }
174	    }
175	
176	    public List<Message> all() {
177	        try (Connection connection = dataSource.getConnection();
178	                PreparedStatement select = connection.prepareStatement(
179	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
180	                ResultSet rows = select.executeQuery()) {
181	            List<Message> messages = new ArrayList<>();
182	            while (rows.next()) {
183	                messages.add(new Message(
184	                        rows.getLong("id"),
185	                        rows.getString("channel"),
186	                        rows.getString("recipient"),
187	                        rows.getString("subject"),
188	                        rows.getString("body")));
189	            }
190	            return messages;
191	        } catch (SQLException failure) {
192	            throw new IllegalStateException("could not read the sent messages", failure);
193	        }
194	    }
195	}

